@Test
void 전략_필드_동시성() throws Exception {
    var t = new TraceTemplate(trace, null);
    var t1 = new Thread(() -> { t.setCallback(() -> "A"); sleep(100);
                                log.info("A 결과 {}", t.execute("A")); });
    var t2 = new Thread(() -> { t.setCallback(() -> "B");
                                log.info("B 결과 {}", t.execute("B")); });
    t1.start(); sleep(50); t2.start(); t1.join(); t2.join();
}

